/// <summary>
/// Extension of GUPPriceComponentCodeGroup
/// MPJ_24248 Pricing Data Extract
/// </summary>
[ExtensionOf(tableStr(GUPPriceComponentCodeGroup))]
Public final class METGUPPriceComponentCodeGroupTable_Extension
{
}

Method.Source:
    /// <summary>
    /// Modified field
    /// </summary>
    /// <param name = "_fieldId">Field id</param>
    public void modifiedField(FieldId _fieldId)
    {
        next modifiedField(_fieldId);

        switch(_fieldId)
        {
            case fieldNum(GUPPriceComponentCodeGroup, priceComponent):
                if(this.priceComponent != GUPPriceComponent::RetailDiscounts)
                {
                    this.METPromotionCode = NoYes::No;   
                }
                break;
        }

    }
